public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }
            return val * sign;
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double EPS = 1e-9;

    static double dist(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return Math.hypot(dx, dy);
    }

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static boolean onSegment(Point a, Point b, Point p) {
        return Math.min(a.x, b.x) - EPS <= p.x && p.x <= Math.max(a.x, b.x) + EPS &&
               Math.min(a.y, b.y) - EPS <= p.y && p.y <= Math.max(a.y, b.y) + EPS &&
               Math.abs(cross(a, b, p)) <= EPS;
    }

    static boolean segmentsIntersect(Point a, Point b, Point c, Point d) {
        double c1 = cross(a, b, c);
        double c2 = cross(a, b, d);
        double c3 = cross(c, d, a);
        double c4 = cross(c, d, b);

        if (((c1 > EPS && c2 < -EPS) || (c1 < -EPS && c2 > EPS)) &&
            ((c3 > EPS && c4 < -EPS) || (c3 < -EPS && c4 > EPS))) {
            return true;
        }

        if (Math.abs(c1) <= EPS && onSegment(a, b, c)) return true;
        if (Math.abs(c2) <= EPS && onSegment(a, b, d)) return true;
        if (Math.abs(c3) <= EPS && onSegment(c, d, a)) return true;
        if (Math.abs(c4) <= EPS && onSegment(c, d, b)) return true;

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point A = new Point(fs.nextDouble(), fs.nextDouble());
        Point B = new Point(fs.nextDouble(), fs.nextDouble());
        Point C = new Point(fs.nextDouble(), fs.nextDouble());
        Point D = new Point(fs.nextDouble(), fs.nextDouble());

        // We need two straight non-intersecting roads:
        // one connecting one Totata town with one Tutete town,
        // so that finally A is connected with B and C with D.
        //
        // Only two pairings are possible:
        // (A-C and B-D) or (A-D and B-C)
        //
        // Among pairings whose segments do not intersect, choose minimum total length.

        double ans = Double.POSITIVE_INFINITY;

        if (!segmentsIntersect(A, C, B, D)) {
            ans = Math.min(ans, dist(A, C) + dist(B, D));
        }
        if (!segmentsIntersect(A, D, B, C)) {
            ans = Math.min(ans, dist(A, D) + dist(B, C));
        }

        if (Double.isInfinite(ans)) {
            System.out.println(-1);
        } else {
            System.out.printf(Locale.US, "%.10f%n", ans);
        }
    }
}

