import sys
import math

eps = 1e-12

def dist(p, q):
    return math.hypot(p[0] - q[0], p[1] - q[1])

def orient(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def on_segment(a, b, p):
    return (min(a[0], b[0]) - eps <= p[0] <= max(a[0], b[0]) + eps and
            min(a[1], b[1]) - eps <= p[1] <= max(a[1], b[1]) + eps)

def segments_intersect(a, b, c, d):
    o1 = orient(a, b, c)
    o2 = orient(a, b, d)
    o3 = orient(c, d, a)
    o4 = orient(c, d, b)

    if (o1 * o2 < -eps) and (o3 * o4 < -eps):
        return True

    if abs(o1) <= eps and on_segment(a, b, c):
        return True
    if abs(o2) <= eps and on_segment(a, b, d):
        return True
    if abs(o3) <= eps and on_segment(c, d, a):
        return True
    if abs(o4) <= eps and on_segment(c, d, b):
        return True

    return False

def main():
    data = list(map(float, sys.stdin.read().strip().split()))
    if len(data) != 8:
        return

    A = (data[0], data[1])
    B = (data[2], data[3])
    C = (data[4], data[5])
    D = (data[6], data[7])

    # Two possible pairings:
    # 1) A-B and C-D
    # 2) A-D and C-B
    # Need non-intersecting straight segments, minimize total length.
    ans = float('inf')

    if not segments_intersect(A, B, C, D):
        ans = min(ans, dist(A, B) + dist(C, D))

    if not segments_intersect(A, D, C, B):
        ans = min(ans, dist(A, D) + dist(C, B))

    if ans == float('inf'):
        print(-1)
    else:
        print(f"{ans:.10f}")

if __name__ == "__main__":
    main()
